package recipe

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/colony-2/c2j/pkg/objects"
	"github.com/stretchr/testify/require"
	"gopkg.in/yaml.v3"
)

// Golden JSON, YAML, and hash were generated by the unmodified f1a153b898c5
// implementation. This protects histories and caches against accidentally
// serializing normalized checkpoint types or newly introduced zero fields.
func TestLegacyRecipeEncodingAndHashUnchanged(t *testing.T) {
	read := func(name string) []byte {
		raw, err := os.ReadFile("testdata/schema_v1" + name)
		require.NoError(t, err)
		return raw
	}
	for _, source := range [][]byte{read(".yaml"), read(".canonical.yaml")} {
		rec, err := LoadInternalRecipeFromString(source)
		require.NoError(t, err)
		_, err = rec.GetMetadata().ValidateInputShapeAndFillDefaults(map[string]any{"session": objects.ValidationRef("test.session/v1")})
		require.NoError(t, err)
		encoded, err := json.Marshal(rec)
		require.NoError(t, err)
		require.Equal(t, string(read(".json")), string(encoded))
		encoded, err = yaml.Marshal(rec)
		require.NoError(t, err)
		require.Equal(t, string(read(".canonical.yaml")), string(encoded))
		require.Equal(t, strings.TrimSpace(string(read(".sha256"))), NewHashComputer().ComputeRecipeHash(rec))
	}
}
